import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  auth: vi.fn(),
  user: vi.fn(),
  checkout: vi.fn(),
  portal: vi.fn(),
  status: vi.fn(),
  cancel: vi.fn(),
  rate: vi.fn(),
}));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/db", () => ({
  db: {
    user: { findUnique: mocks.user },
    billingRateLimit: { upsert: mocks.rate },
  },
}));
vi.mock("@/lib/billing/checkout", () => ({
  createBillingCheckout: mocks.checkout,
  createBillingPortal: mocks.portal,
}));
vi.mock("@/lib/billing/status", () => ({ readBillingStatus: mocks.status }));
vi.mock("@/lib/billing/cancel", () => ({
  cancelBillingSubscription: mocks.cancel,
}));
vi.mock("@/lib/rate-limit", async (original) => ({
  ...(await original<typeof import("@/lib/rate-limit")>()),
  consumeBudgets: mocks.rate,
}));
import { RateLimitError } from "@/lib/rate-limit";
import { POST as cancel } from "@/app/api/billing/cancel/route";
import { POST as checkout } from "@/app/api/billing/checkout/route";
import { POST as portal } from "@/app/api/billing/portal/route";
import { GET as status } from "@/app/api/billing/status/route";

beforeEach(() => {
  vi.resetAllMocks();
  mocks.rate.mockResolvedValue({ requestCount: 1 });
  mocks.cancel.mockResolvedValue({ cancellationPending: true });
  mocks.auth.mockResolvedValue({ user: { id: "session-owner" } });
  mocks.user.mockResolvedValue({
    id: "session-owner",
    deletionRequestedAt: null,
    isSuspended: false,
  });
  for (const [key, value] of Object.entries({
    DODO_PAYMENTS_ENVIRONMENT: "test_mode",
    DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
    DODO_PAYMENTS_WEBHOOK_KEY: "fixture",
    DODO_PAYMENTS_BUSINESS_ID: "bus_fixture",
    DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_fixture",
    AUTH_URL: "http://localhost:3000",
  }))
    vi.stubEnv(key, value);
  mocks.checkout.mockResolvedValue({
    checkoutUrl: "https://test.checkout.dodopayments.com/session/fixture",
  });
  mocks.portal.mockResolvedValue({
    portalUrl: "https://test.customer.dodopayments.com/session/fixture",
  });
  mocks.status.mockResolvedValue({
    configured: true,
    mode: "test",
    plan: "FREE",
    status: "PENDING",
  });
});
afterEach(() => vi.unstubAllEnvs());
const request = (body: unknown = {}, origin = "http://localhost:3000") =>
  new Request("http://untrusted-host/api/billing/checkout", {
    method: "POST",
    headers: { origin },
    body: JSON.stringify(body),
  });
describe("billing HTTP authentication and origin boundary", () => {
  it("authenticates every user-facing route before any provider operation", async () => {
    mocks.auth.mockResolvedValue(null);
    for (const call of [
      () => checkout(request()),
      () => portal(request()),
      () => status(),
      () => cancel(request()),
    ]) {
      const response = await call();
      expect(response.status).toBe(401);
      expect(response.headers.get("Cache-Control")).toBe("private, no-store");
    }
    expect(mocks.checkout).not.toHaveBeenCalled();
    expect(mocks.portal).not.toHaveBeenCalled();
    expect(mocks.status).not.toHaveBeenCalled();
  });
  it("takes the owner from the verified session, not a request body", async () => {
    await checkout(request({ plan: "paid_monthly", userId: "attacker" }));
    expect(mocks.checkout).toHaveBeenCalledWith(
      "session-owner",
      expect.any(Object),
    );
    await portal(request({ customerId: "attacker" }));
    expect(mocks.portal).toHaveBeenCalledWith("session-owner");
    await status();
    expect(mocks.status).toHaveBeenCalledWith("session-owner");
  });
  it("uses the configured origin even if the incoming host is untrusted", async () => {
    expect(
      (await checkout(request({}, "https://attacker.example"))).status,
    ).toBe(403);
    expect((await portal(request({}, "https://attacker.example"))).status).toBe(
      403,
    );
    expect(mocks.checkout).not.toHaveBeenCalled();
    expect(mocks.portal).not.toHaveBeenCalled();
    expect((await checkout(request())).status).toBe(200);
  });
  it("accepts the canonical www production origin without accepting other origins", async () => {
    vi.stubEnv("AUTH_URL", "https://mailloop.in");
    expect(
      (await checkout(request({}, "https://www.mailloop.in"))).status,
    ).toBe(200);
    expect((await portal(request({}, "https://www.mailloop.in"))).status).toBe(
      200,
    );
    expect((await cancel(request({}, "https://www.mailloop.in"))).status).toBe(
      200,
    );
    expect(
      (await checkout(request({}, "https://mailloop.in.attacker.example")))
        .status,
    ).toBe(403);
  });
  it("rejects deletion-pending users and malformed JSON without exposing errors", async () => {
    mocks.user.mockResolvedValueOnce({
      id: "session-owner",
      deletionRequestedAt: new Date(),
    });
    expect((await checkout(request())).status).toBe(403);
    expect(
      (
        await checkout(
          new Request("http://localhost/api/billing/checkout", {
            method: "POST",
            headers: { origin: "http://localhost:3000" },
            body: "{",
          }),
        )
      ).status,
    ).toBe(400);
    mocks.status.mockRejectedValueOnce(
      new Error("sensitive-provider-response"),
    );
    const response = await status();
    expect(response.status).toBe(503);
    expect(await response.text()).not.toContain("sensitive-provider-response");
  });
});

describe("billing rate limits and cancellation", () => {
  it.each([
    ["checkout", 6],
    ["portal", 11],
    ["cancel", 11],
    ["status", 31],
  ] as const)(
    "limits %s per authenticated owner",
    async (operation, _requestCount) => {
      expect(_requestCount).toBeGreaterThan(0);
      mocks.rate.mockRejectedValue(new RateLimitError(60));
      const handlers = { checkout, portal, cancel, status: () => status() };
      const response = await handlers[operation](request());
      expect(response.status).toBe(429);
      expect(Number(response.headers.get("Retry-After"))).toBeGreaterThan(0);
      expect(Number(response.headers.get("Retry-After"))).toBeLessThanOrEqual(
        60,
      );
      expect(mocks.rate).toHaveBeenCalledWith("session-owner", [
        operation === "portal" || operation === "cancel"
          ? "billingManagement"
          : operation,
      ]);
    },
  );
  it("uses the session owner for cancellation and returns only pending state", async () => {
    const response = await cancel(request());
    expect(mocks.cancel).toHaveBeenCalledWith("session-owner", {});
    expect(await response.json()).toEqual({ cancellationPending: true });
  });
  it("allows suspended owners to read status and manage or cancel billing", async () => {
    mocks.user.mockResolvedValue({
      id: "session-owner",
      deletionRequestedAt: null,
      isSuspended: true,
    });
    expect((await status()).status).toBe(200);
    expect((await portal(request())).status).toBe(200);
    expect((await cancel(request())).status).toBe(200);
    expect(mocks.portal).toHaveBeenCalledWith("session-owner");
    expect(mocks.cancel).toHaveBeenCalledWith("session-owner", {});
  });
  it("rejects a foreign cancellation origin and malformed body", async () => {
    expect((await cancel(request({}, "https://foreign.example"))).status).toBe(
      403,
    );
    expect(
      (
        await cancel(
          new Request("http://localhost", {
            method: "POST",
            headers: { origin: "http://localhost:3000" },
            body: "{",
          }),
        )
      ).status,
    ).toBe(400);
    expect(mocks.cancel).not.toHaveBeenCalled();
  });
  it("exposes only the hosted URL in checkout and portal responses", async () => {
    expect(Object.keys(await (await checkout(request())).json())).toEqual([
      "checkoutUrl",
    ]);
    expect(Object.keys(await (await portal(request())).json())).toEqual([
      "portalUrl",
    ]);
  });
});
